	v, ok := f.KV[key].([]uint64)
	return v, ok
}

// Ints reads a metadata value as a signed integer array.
func (f *File) Ints(key string) ([]int64, bool) {
	v, ok := f.KV[key].([]int64)
	return v, ok
}

