	clip := func(v int32) uint8 {
		v >>= p.prec
		if v < 0 {
			return 0
		}
		if v > 255 {
			return 255
		}
		return uint8(v)
	}
	for o := 0; o < size; o++ {
		xmin, n := p.bounds[o][0], p.bounds[o][1]
		kk := p.kk[o*p.ksize:][:n]
		if horizontal {
			for y := 0; y < src.H; y++ {
				row := src.Pix[y*src.W*3:]
				var r, g, b int32 = round, round, round
				for j, w := range kk {
					s := row[(xmin+j)*3:]
					r += int32(s[0]) * w
					g += int32(s[1]) * w
					b += int32(s[2]) * w
				}
				d := out.Pix[(y*out.W+o)*3:]
				d[0], d[1], d[2] = clip(r), clip(g), clip(b)
			}
			continue
		}
		for x := 0; x < src.W; x++ {
			var r, g, b int32 = round, round, round
			for j, w := range kk {
				s := src.Pix[((xmin+j)*src.W+x)*3:]
				r += int32(s[0]) * w
				g += int32(s[1]) * w
				b += int32(s[2]) * w
			}
			d := out.Pix[(o*out.W+x)*3:]
			d[0], d[1], d[2] = clip(r), clip(g), clip(b)
		}
	}
	return out
}

