		if err != nil {
			t.Fatal(err)
		}
		t.Logf("%s: %dx%d patches", card, gr[1], gr[2])
		compareAt(t, card+" last_hidden", out.Last, llmRef(t, ref, card+"_last_hidden"), llmFP16Tol)
		compareAt(t, card+" merged", out.Merged, llmRef(t, ref, card+"_merged"), llmFP16Tol)
	}
}

// llmFP16Tol: see LLM-VISION.md V4.
