		j := min(i+dispatchesPerSubmit, len(ds))
		if _, err := vk.DispatchMultiTimed(ds[i:j], 1, 1, true); err != nil {
			return fmt.Errorf("vision: dispatch %d-%d: %w", i, j-1, err)
		}
	}
	return nil
}

