			dd += (g - w) * (g - w)
			ww += w * w
			gw += g * w
			gg += g * g
			wr += w * w
		}
		if cos := gw / math.Sqrt(gg*wr); cos < worstCos {
			worstCos = cos
		}
	}
	return math.Sqrt(dd / ww), worstCos
