			t.Fatal(err)
		}
		again, err := g.HiddenExtendInput(Input{IDs: all[:nTok]})
		if err != nil {
			t.Fatal(err)
		}
		for i := range plain {
			if plain[i] != again[i] {
				t.Fatalf("a text prompt after an image sequence differs from itself at %d", i)
			}
		}
		t.Log("an image's rows are repaired for the next image and for text")
	})
}
