		}
		return idx[a] < idx[b]
	})
	return idx[:k]
}

// sameSet counts how many of b appear in a, order ignored.
func sameSet(a, b []int) int {
	in := make(map[int]bool, len(a))
	for _, v := range a {
		in[v] = true
	}
	n := 0
	for _, v := range b {
		if in[v] {
			n++
		}
	}
	return n
}

