func (s *llmSched) loop() {
	defer close(s.stopped)
	for {
		s.mu.Lock()
		var u *llmUnit
		var steps []*llmUnit
		for {
			if s.closed {
				for _, p := range s.pending {
					p.err = errors.New("the language model is closed")
					close(p.done)
				}
				s.pending = nil
				s.mu.Unlock()
				return
			}
			if u = s.pick(); u != nil {
				if !u.step {
					break
				}
				steps = s.steps(u)
				wait := s.coalesceWait(u, len(steps))
				if wait <= 0 {
					break
				}
				time.AfterFunc(wait, func() {
					s.mu.Lock()
					s.wake.Broadcast()
					s.mu.Unlock()
				})
			}
			s.wake.Wait()
		}
		if len(steps) > 1 {
			s.runSteps(steps)
			continue
		}
		n := min(len(u.ids), s.batch)
		if u.job.class == classBackground && s.preempt > 0 && len(u.ids) > 1 {
			n = min(n, s.preempt)
		}
		slot, fresh, restore := u.job.slot, u.fresh, u.restore
		sl := &s.slots[slot]
		var ck *llm.Checkpoint
		pos := len(sl.held)
		switch {
		case fresh:
			pos = 0
		case restore:
			ck = sl.ckpt
			pos = ck.Past()
		}
		// The chunk that reaches the checkpoint's boundary ends there.
		mark := u.job.mark
		if mark > pos && mark < pos+n {
			n = mark - pos
		}
		take := mark > 0 && pos+n == mark
		chunk, next := u.ids[:n], u.ids[n:min(len(u.ids), 2*n)]
		keep := sl.ckpt
		s.running = u
		s.mu.Unlock()

		var logits []float32
		t0 := time.Now()
		ran := false
		err := u.job.ctx.Err()
		if err == nil {
			ran = true
			err = s.dev.Do(func(*vk.Device) error {
				if err := s.g.UseSlot(slot); err != nil {
					return err
				}
				if len(next) > 0 {
