// requestImage is one image as the request sent it, in conversation order.
type requestImage struct {
	url string
}

// decodeDataURL reads `data:<type>;base64,<payload>`. A remote URL is
// refused: this server does not fetch on a client's behalf (LLM-VISION.md
// Q3), and an image that arrives as a link is one the client can send as
// bytes.
func decodeDataURL(url string) ([]byte, error) {
	if !strings.HasPrefix(url, "data:") {
		kind := url
		if i := strings.Index(kind, ":"); i > 0 && i < 10 {
			kind = kind[:i]
		} else {
			kind = "a non-data"
		}
		return nil, fmt.Errorf("an image given as a %s URL; this server does not fetch images, "+
			"so send it inline as a data: URL (base64)", kind)
	}
	meta, payload, ok := strings.Cut(url[len("data:"):], ",")
	if !ok || !strings.HasSuffix(meta, ";base64") {
		return nil, fmt.Errorf("an image data: URL that is not base64")
	}
	b, err := base64.StdEncoding.DecodeString(payload)
	if err != nil {
		if b, err = base64.RawStdEncoding.DecodeString(payload); err != nil {
			return nil, fmt.Errorf("an image data: URL whose payload is not base64: %v", err)
		}
	}
	return b, nil
}

// encode turns one image into the prompt's rows. It returns the tower time
// for the request's log line.
func (v *llmVision) encode(dev *Device, img requestImage) (llm.PromptImage, time.Duration, error) {
	data, err := decodeDataURL(img.url)
	if err != nil {
		return llm.PromptImage{}, 0, fmt.Errorf("%v: %w", err, api.ErrUnsupported)
	}
	rgb, _, err := pixels.Decode(data)
	if err != nil {
		return llm.PromptImage{}, 0, fmt.Errorf("%v: %w", err, api.ErrUnsupported)
	}
	planes, h, w, err := v.proc.Planes(rgb)
	if err != nil {
		return llm.PromptImage{}, 0, fmt.Errorf("%v: %w", err, api.ErrUnsupported)
	}
	rows, gh, gw, err := v.cfg.Patchify(planes, h, w)
	if err != nil {
		return llm.PromptImage{}, 0, err
	}
	var out *vision.Output
	start := time.Now()
	err = dev.Do(func(*vk.Device) error {
		var err error
		out, err = v.gpu.Forward(nilContext{}, rows, gh, gw)
		return err
	})
	if err != nil {
		return llm.PromptImage{}, 0, fmt.Errorf("vision tower: %w", err)
	}
	sum := sha256.Sum256(data)
	return llm.PromptImage{
		GridH: gh / v.cfg.SpatialMergeSize, GridW: gw / v.cfg.SpatialMergeSize,
		Hash: binary.LittleEndian.Uint64(sum[:8]), Embd: out.Merged.Data,
	}, time.Since(start), nil
}

var _ = qwen.NewMat

// imageKey is an image cell's scheduling key: negative, so it can never be
// a token id, and a function of the image's hash and the cell's place in it.
func imageKey(hash uint64, k int) int32 {
	h := hash ^ uint64(k+1)*0x9e3779b97f4a7c15
