    req=urllib.request.Request("http://127.0.0.1:18080"+path,json.dumps(body).encode(),{"Content-Type":"application/json"})
    try:
        r=urllib.request.urlopen(req)
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode()
    if not stream: return 200, json.load(r)
    out=[]
    for line in r:
        line=line.decode().strip()
        if line.startswith("data: ") and line!="data: [DONE]":
            d=json.loads(line[6:])["choices"][0]["delta"]
            out.append(d.get("content") or "")
    return 200, "".join(out)
kw={"chat_template_kwargs":{"enable_thinking":False},"temperature":0}
t1=[{"role":"user","content":[{"type":"image_url","image_url":{"url":big}},{"type":"text","text":"Describe this photo in one sentence."}]}]
c,r=post("/v1/chat/completions",{"max_tokens":60,"messages":t1,"stream":True,**kw},stream=True); print("stream:",c,r)
t2=t1+[{"role":"assistant","content":r},{"role":"user","content":"What time of day is it?"}]
c,r=post("/v1/chat/completions",{"max_tokens":40,"messages":t2,**kw}); print("turn 2:",c,r["choices"][0]["message"]["content"])
